  function detectLang() {
    try {
      const saved = localStorage.getItem('loky_user_lang');
      if (saved && saved !== 'auto') {
        if (saved === 'ar' || LANGS.includes(saved)) return saved;
      }
    } catch (e) {}
    const list = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']);
    for (const raw of list) {
      let code = String(raw || '').toLowerCase().split(/[-_]/)[0];
      if (code === 'in') code = 'id'; // legacy Android code for Indonesian
      if (code === 'ar' || LANGS.includes(code)) return code;
    }
    return 'en';
  }

  window.setAppLanguage = function(lang) {
    try {
      if (!lang || lang === 'auto') {
        localStorage.removeItem('loky_user_lang');
      } else {
        localStorage.setItem('loky_user_lang', lang);
      }
      window.location.reload();
    } catch (e) {
      window.location.reload();
    }
  };

